files=sorted(glob.glob('product_audit/batches_v2/A001_in_0*.out.json'))+['product_audit/batches_v2/A001_v2_a.out.json','product_audit/batches_v2/A001_v2_b.out.json']
changed=0
for f in files:
    d=json.load(open(f))
    for x in d:
        for k in ('d','merchant'):
            t=x[k]
            for s,alts in R.items():
                for form in (s,s.replace('&','&amp;')):
                    if form in t:
                        i=x['n']%(len(alts)+1)
                        if i>0:
                            rep=alts[i-1] if form==s else alts[i-1].replace('&','&amp;')
                            t=t.replace(form,rep); changed+=1
            x[k]=t
        pr=check(x)
        if pr: print('PROBLEM after variation',x['n'],pr)
    json.dump(d,open(f,'w'),ensure_ascii=False,indent=0)
print('sentences varied:',changed)
